#!/bin/zsh
# Runs the Argent e2e suite (apps/harness/.argent/e2e, generated by build.py) on one booted simulator
# or emulator with the Release harness installed, then writes e2e/results/argent/review.html.
#   e2e/argent/run.sh <simulator UDID or adb serial> [name filter]
U=$1; FILTER=${2:-}; H=${0:a:h:h:h}
[[ -z $U ]] && { echo "usage: run.sh <device> [filter]" >&2; exit 2; }
cd $H || exit 1
echo $U > .argent/device
FAILED=()
for test in .argent/e2e/*.yaml; do
  name=${test:t:r}
  [[ -n $FILTER && $name != *$FILTER* ]] && continue
  if argent e2e run $name --device $U > e2e/results/argent-$name.log 2>&1; then
    printf "%-28s pass %s\n" $name "$(grep -o 'blank [0-9]*, flicker [0-9]*, jump [0-9]*' e2e/results/argent-$name.log | tail -1)"
  else
    FAILED+=$name
    printf "%-28s FAIL %s\n" $name "$(grep -m1 -E '✗|errored' e2e/results/argent-$name.log | cut -c1-140)"
  fi
done
python3 -I e2e/visual/review.py e2e/results/argent
echo "${#FAILED} failed${FAILED:+: $FAILED}"
(( ${#FAILED} == 0 ))
